import{_ as i,C as n,o as r,c as o,a2 as t,E as s}from"./chunks/framework.CBxkvBm_.js";const f=JSON.parse('{"title":"Pantelides Structural Index Reduction","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/pantelides.md","filePath":"algorithms/pantelides.md"}'),l={name:"algorithms/pantelides.md"};function d(c,e,m,h,u,p){const a=n("MermaidBlock");return r(),o("div",null,[e[0]||(e[0]=t('<h1 id="pantelides-structural-index-reduction" tabindex="-1">Pantelides Structural Index Reduction <a class="header-anchor" href="#pantelides-structural-index-reduction" aria-label="Permalink to &quot;Pantelides Structural Index Reduction&quot;">​</a></h1><p><strong>Implementation</strong>: <code>PantelidesEngine</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/structural/pantelides.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/structural/pantelides.ts</code></a></p><hr><h2 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h2><ul><li><strong>Pantelides, C. C. (1988)</strong>. <em>&quot;The consistent initialization of differential-algebraic systems.&quot;</em><br><strong>SIAM Journal on Scientific and Statistical Computing</strong>, 9(2), pp. 213–231.<br> DOI: <a href="https://doi.org/10.1137/0909014" target="_blank" rel="noreferrer">10.1137/0909014</a></li><li><strong>Mattsson, S. E., &amp; Söderlind, G. (1993)</strong>. <em>&quot;Index reduction in differential-algebraic equations using dummy derivatives.&quot;</em><br><strong>SIAM Journal on Scientific Computing</strong>, 14(3), pp. 677–692.<br> DOI: <a href="https://doi.org/10.1137/0914043" target="_blank" rel="noreferrer">10.1137/0914043</a></li></ul><hr><h2 id="modelscript-architectural-rationale" tabindex="-1">ModelScript Architectural Rationale <a class="header-anchor" href="#modelscript-architectural-rationale" aria-label="Permalink to &quot;ModelScript Architectural Rationale&quot;">​</a></h2><p>Object-oriented multi-domain physical models (such as constrained multi-body mechanics, closed kinematic linkages, and incompressible hydraulic loops) inherently generate high-index Differential-Algebraic Equations (DAEs) where the differential index satisfies $\\text{ind} \\ge 2$:</p><p>$$F(t, x, \\dot{x}, y) = 0$$</p><p>Standard numerical integrators (including BDF, Radau, and Runge-Kutta methods) become severely ill-conditioned or fail to converge on systems with differential index greater than 1.</p><p>Pantelides&#39; algorithm identifies minimally singular subsets of equations and differentiates them analytically with respect to time until an index-1 or index-0 formulation is attained. To prevent over-determination and numerical drift along algebraic constraint manifolds, the Mattsson-Söderlind dummy derivative method dynamically replaces redundant derivative states with algebraic placeholders.</p><hr><h2 id="modelscript-modifications-wasm-architecture" tabindex="-1">ModelScript Modifications &amp; WASM Architecture <a class="header-anchor" href="#modelscript-modifications-wasm-architecture" aria-label="Permalink to &quot;ModelScript Modifications &amp; WASM Architecture&quot;">​</a></h2><ol><li><strong>In-WASM Linear Memory Execution</strong>: Operates as an unmanaged WebAssembly kernel (<code>@unmanaged</code>) with zero garbage collection allocations.</li><li><strong>Direct Arena Symbolic Differentiation</strong>: Derivatives of equations ($\\frac{d^k f}{dt^k} = 0$) are differentiated directly on <code>DAEBuilder</code> linear expression nodes in memory.</li><li><strong>Flat Chunked Arrays</strong>: Equation dependency incidence pointers, differentiation levels, and matching arrays are stored in flat <code>ChunkedInt32Array</code> buffers.</li><li><strong>Augmenting Path Bipartite Matching</strong>: Alternating path searches run directly over highest-derivative variables, seamlessly transferring matching data to the downstream <code>BltEngine</code>.</li></ol><hr><h2 id="algorithm-description-mathematics" tabindex="-1">Algorithm Description &amp; Mathematics <a class="header-anchor" href="#algorithm-description-mathematics" aria-label="Permalink to &quot;Algorithm Description &amp; Mathematics&quot;">​</a></h2>',16)),s(a,{code:"flowchart%20TD%0A%20%20%20%20INIT%5B%22Initialize%20Equation%20Differentiation%20Levels%3A%20k_i%20%3D%200%22%5D%20--%3E%20MATCH%5B%22Construct%20Bipartite%20Graph%20G%20%3D%20(E%2C%20V)%3Cbr%2F%3EEdges%20connecting%20eq_i%5E(k_i)%20to%20highest%20derivative%20vars%22%5D%0A%20%20%20%20MATCH%20--%3E%20AUG%5B%22Find%20Augmenting%20Path%20for%20eq_i%22%5D%0A%20%20%20%20AUG%20--%3E%7CPath%20Found%7C%20NEXT%5B%22Assign%20match(eq_i)%20%3D%20v_j%3B%20proceed%20to%20next%20equation%22%5D%0A%20%20%20%20AUG%20--%3E%7CNo%20Augmenting%20Path%7C%20DIFF%5B%22Subset%20S_E%20cannot%20be%20matched!%3Cbr%2F%3EDifferentiate%20all%20equations%20in%20S_E%3A%20k_m%20%E2%86%90%20k_m%20%2B%201%3Cbr%2F%3EDifferentiate%20all%20variables%20in%20S_V%22%5D%0A%20%20%20%20DIFF%20--%3E%20MATCH%0A%20%20%20%20NEXT%20--%3E%20CHECK%7B%22All%20equations%20matched%3F%22%7D%0A%20%20%20%20CHECK%20--%3E%7CNo%7C%20AUG%0A%20%20%20%20CHECK%20--%3E%7CYes%7C%20DUMMY%5B%22Apply%20Mattsson-S%C3%B6derlind%20Dummy%20Derivative%20Selection%22%5D%0A"}),e[1]||(e[1]=t('<h3 id="mathematical-steps" tabindex="-1">Mathematical Steps <a class="header-anchor" href="#mathematical-steps" aria-label="Permalink to &quot;Mathematical Steps&quot;">​</a></h3><ol><li><strong>Variable Classification</strong>: Identify highest-order derivatives $\\dot{x}_j$ and purely algebraic variables $y_k$.</li><li><strong>Alternating Augmenting Paths</strong>: For each equation $f_i = 0$, attempt to find an augmenting path in the bipartite incidence graph to an unmatched highest-order derivative.</li><li><strong>Index Reduction by Differentiation</strong>: If no augmenting path exists, the reachable set of equations $S_E$ is structurally singular. Increment the differentiation index $k_m \\leftarrow k_m + 1$ for all $f_m \\in S_E$, symbolically compute $\\frac{d f_m}{dt}$, and repeat the matching.</li><li><strong>Dummy Derivatives</strong>: For each differentiated state variable where both $x_j$ and $\\dot{x}<em>j$ appear in algebraic constraints, select a dummy algebraic variable $x</em>{j,\\text{dummy}}$ to replace $\\dot{x}_j$, preserving degrees of freedom.</li></ol><hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>Ingests the flat DAE representation from <code>DAEBuilder</code> produced by <a href="./../architecture/dae-arena.html"><code>ModelicaFlattener</code></a>.</li><li>Uses <code>Cst</code> linear nodes for symbolic expressions.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Feeds the index-reduced DAE directly into <a href="./blt.html"><code>BltEngine</code></a> for block lower triangular partitioning.</li><li>Determines consistent initial conditions for <a href="./solvers-ode-dae.html"><code>SUNDIALS IDA</code></a> and <a href="./solvers-ode-dae.html"><code>TR-BDF2</code></a>.</li></ul></li></ul>',5))])}const b=i(l,[["render",d]]);export{f as __pageData,b as default};
